(function(){
'use strict';
var RESTARTS={'no':'从不自动重启','on-success':'正常退出后重启','on-failure':'异常退出/超时才重启',
  'on-abnormal':'被信号杀死或超时才重启','on-abort':'收到未捕获信号才重启','on-watchdog':'看门狗超时才重启','always':'无论如何都重启'};
var TYPES={'simple':'ExecStart 进程即主进程，启动后立即视为就绪','exec':'与 simple 类似但等到 execve 成功才算启动完成',
  'forking':'主进程会 fork 后退出，需配合 PIDFile','oneshot':'跑完就退出，常配合 RemainAfterExit',
  'notify':'服务通过 sd_notify 主动上报就绪','idle':'延迟到其他任务派发完再启动','dbus':'服务就绪以取得 D-Bus 名称为准'};
function esc(v){ return String(v==null?'':v).replace(/\r?\n/g,' ').trim(); }
function build(o){
  o=o||{};
  var name=esc(o.name||'myapp');
  if(!/^[A-Za-z0-9_.@-]+$/.test(name)) return {value:null,error:'服务名只能包含字母、数字与 _ . @ -'};
  var exec=esc(o.execStart||'');
  if(!exec) return {value:null,error:'请填写 ExecStart 启动命令'};
  var L=[],warn=[];
  L.push('[Unit]');
  L.push('Description='+esc(o.description||(name+' service')));
  if(o.documentation) L.push('Documentation='+esc(o.documentation));
  L.push('After='+esc(o.after||'network-online.target'));
  if((o.after||'network-online.target').indexOf('network-online')>=0) L.push('Wants=network-online.target');
  if(o.requires) L.push('Requires='+esc(o.requires));
  L.push('');
  L.push('[Service]');
  var type=o.type||'simple';
  L.push('Type='+type);
  if(type==='oneshot'&&o.remain!==false) L.push('RemainAfterExit=yes');
  if(type==='forking'&&o.pidfile) L.push('PIDFile='+esc(o.pidfile));
  if(o.user) L.push('User='+esc(o.user));
  if(o.group) L.push('Group='+esc(o.group));
  if(o.workdir) L.push('WorkingDirectory='+esc(o.workdir));
  if(o.envFile) L.push('EnvironmentFile=-'+esc(o.envFile));
  var envs=(o.env||'').split(/\r?\n/).filter(function(x){return x.trim();});
  for(var i=0;i<envs.length;i++){
    var kv=envs[i].trim();
    L.push('Environment='+(/\s/.test(kv)?('"'+kv+'"'):kv));
  }
  L.push('ExecStart='+exec);
  if(o.execReload) L.push('ExecReload='+esc(o.execReload));
  if(o.execStop) L.push('ExecStop='+esc(o.execStop));
  var restart=o.restart||'on-failure';
  if(type!=='oneshot'){
    L.push('Restart='+restart);
    if(restart!=='no') L.push('RestartSec='+(o.restartSec||'5'));
  }
  if(o.timeout) L.push('TimeoutStopSec='+esc(o.timeout));
  if(o.hardening!==false){
    L.push('NoNewPrivileges=yes');
    L.push('PrivateTmp=yes');
    L.push('ProtectSystem=strict');
    L.push('ProtectHome=yes');
    if(o.workdir) L.push('ReadWritePaths='+esc(o.workdir));
  }
  if(o.limitNofile) L.push('LimitNOFILE='+esc(o.limitNofile));
  L.push('StandardOutput=journal');
  L.push('StandardError=journal');
  L.push('');
  L.push('[Install]');
  L.push('WantedBy='+esc(o.wantedBy||'multi-user.target'));
  var unit=L.join('\n')+'\n';
  var timer='';
  if(o.timer){
    var T=[];
    T.push('[Unit]');
    T.push('Description=Timer for '+name);
    T.push('');
    T.push('[Timer]');
    T.push('OnCalendar='+esc(o.onCalendar||'daily'));
    T.push('Persistent=true');
    T.push('AccuracySec=1min');
    T.push('Unit='+name+'.service');
    T.push('');
    T.push('[Install]');
    T.push('WantedBy=timers.target');
    timer=T.join('\n')+'\n';
    if(type!=='oneshot') warn.push('定时任务建议把 Type 设为 oneshot，否则 systemd 会认为服务常驻');
  }
  if(!o.user) warn.push('未指定 User，服务将以 root 运行，建议创建专用低权限账号');
  if(exec.charAt(0)!=='/') warn.push('ExecStart 必须使用绝对路径，systemd 不会走 PATH 查找');
  var cmds=['sudo cp '+name+'.service /etc/systemd/system/'+name+'.service',
            'sudo systemctl daemon-reload',
            'sudo systemctl enable --now '+name+(o.timer?'.timer':'.service'),
            'systemctl status '+name,
            'journalctl -u '+name+' -f'];
  return {value:{unit:unit,timer:timer,warn:warn,cmds:cmds,fileName:name+'.service',
                 typeDesc:TYPES[type]||'',restartDesc:RESTARTS[restart]||''},error:null};
}
function parseUnit(text){
  var lines=String(text||'').split(/\r?\n/),sec='',out={},order=[],i;
  for(i=0;i<lines.length;i++){
    var l=lines[i].trim();
    if(!l||l.charAt(0)==='#'||l.charAt(0)===';') continue;
    var m=/^\[([^\]]+)\]$/.exec(l);
    if(m){ sec=m[1]; if(!out[sec]){out[sec]={};order.push(sec);} continue; }
    var j=l.indexOf('=');
    if(j<0) continue;
    var k=l.slice(0,j).trim(),v=l.slice(j+1).trim();
    if(!sec) continue;
    if(!out[sec]) out[sec]={};
    if(out[sec][k]!==undefined) out[sec][k]=[].concat(out[sec][k],v);
    else out[sec][k]=v;
  }
  return {sections:out,order:order};
}
function lint(text){
  if(typeof text!=='string'||!text.trim()) return {value:null,error:'请粘贴 systemd unit 文件内容'};
  var p=parseUnit(text),S=p.sections,issues=[];
  function add(sev,msg,fix){ issues.push({sev:sev,msg:msg,fix:fix||''}); }
  if(!p.order.length) return {value:null,error:'未识别到任何 [Section]，确认这是 unit 文件'};
  var isTimer=!!S['Timer'],isSock=!!S['Socket'];
  if(!S['Unit']) add('error','缺少 [Unit] 段','补上 [Unit] 与 Description');
  else if(!S['Unit']['Description']) add('warning','[Unit] 缺少 Description','加一句人类可读的描述，systemctl 列表才好认');
  if(!isTimer&&!isSock&&!S['Service']) add('error','缺少 [Service] 段','service 单元必须有 [Service]');
  if(S['Service']){
    var sv=S['Service'],type=sv['Type']||'simple';
    if(!sv['ExecStart']&&type!=='oneshot') add('error','[Service] 缺少 ExecStart','指定启动命令的绝对路径');
    var ex=[].concat(sv['ExecStart']||[])[0]||'';
    if(ex){
      var head=ex.replace(/^[-@+!]+/,'').split(/\s+/)[0];
      if(head&&head.charAt(0)!=='/') add('error','ExecStart 不是绝对路径：'+head,'systemd 不解析 PATH，写成 /usr/bin/xxx');
      if(/\bsudo\b/.test(ex)) add('error','ExecStart 中使用了 sudo','改用 User= 指定运行身份');
      if(/[|<>]|&&|\$\(/.test(ex)) add('warning','ExecStart 含 shell 语法（管道/重定向/变量替换）','包一层 /bin/sh -c "..." 或写成脚本');
      if(/\s&\s*$/.test(ex)) add('error','ExecStart 结尾的 & 会让 systemd 误判进程退出','去掉 &，交给 systemd 管理前台进程');
    }
    if(!TYPES[type]) add('warning','未知的 Type='+type,'常用值：simple / exec / forking / oneshot / notify');
    if(type==='forking'&&!sv['PIDFile']) add('warning','Type=forking 未配 PIDFile','systemd 可能追踪不到主进程');
    if(type==='oneshot'&&sv['Restart']&&sv['Restart']!=='no') add('warning','Type=oneshot 配合 Restart='+sv['Restart']+' 会反复拉起','oneshot 通常配 RemainAfterExit=yes 且不重启');
    if(sv['Restart']&&!RESTARTS[sv['Restart']]) add('error','非法的 Restart='+sv['Restart'],'合法值：'+Object.keys(RESTARTS).join(' / '));
    if(sv['Restart']&&sv['Restart']!=='no'&&!sv['RestartSec']) add('info','设置了 Restart 但没有 RestartSec','加 RestartSec=5 避免崩溃时疯狂重启');
    if(!sv['User']) add('info','未指定 User，默认以 root 运行','建议建立专用系统账号并设置 User=');
    else if(sv['User']==='root') add('warning','显式以 root 运行','除非确有必要，否则降权运行');
    if(!sv['NoNewPrivileges']) add('info','未开启 NoNewPrivileges','加 NoNewPrivileges=yes 阻止提权');
    if(!sv['ProtectSystem']) add('info','未开启 ProtectSystem','加 ProtectSystem=strict 只读挂载系统目录');
    if(sv['Environment']){
      var envs=[].concat(sv['Environment']);
      for(var i=0;i<envs.length;i++){
        if(/\s/.test(envs[i])&&envs[i].charAt(0)!=='"') add('warning','Environment 含空格却未加引号：'+envs[i],'写成 Environment="K=a b"');
      }
    }
    if(sv['EnvironmentFile']&&String([].concat(sv['EnvironmentFile'])[0]).charAt(0)!=='-')
      add('info','EnvironmentFile 未加 - 前缀','文件缺失时服务会启动失败，加 - 可容忍缺失');
  }
  if(isTimer){
    var tm=S['Timer'];
    if(!tm['OnCalendar']&&!tm['OnUnitActiveSec']&&!tm['OnBootSec']) add('error','[Timer] 没有任何触发条件','至少设置 OnCalendar= 或 OnBootSec=');
    if(tm['OnCalendar']&&!tm['Persistent']) add('info','OnCalendar 未设 Persistent','设 Persistent=true 可在关机错过后补跑');
  }
  if(!S['Install']&&!isSock) add('warning','缺少 [Install] 段','没有 WantedBy 时 systemctl enable 会失败');
  else if(S['Install']&&!S['Install']['WantedBy']&&!S['Install']['RequiredBy']) add('warning','[Install] 缺少 WantedBy','通常写 WantedBy=multi-user.target');
  var stats={error:0,warning:0,info:0},k;
  for(k=0;k<issues.length;k++) stats[issues[k].sev]++;
  return {value:{issues:issues,stats:stats,sections:p.order,
                 score:Math.max(0,100-stats.error*20-stats.warning*8-stats.info*3)},error:null};
}
var API={build:build,lint:lint,parseUnit:parseUnit,TYPES:TYPES,RESTARTS:RESTARTS};
if(typeof module!=='undefined'&&module.exports) module.exports=API;
if(typeof window!=='undefined') window.__SystemdForge__=API;
})();
